custom_css:
.sc-tw :root{
            --neon-magenta: oklch(65% 0.3 330);
            --electric-cyan: oklch(60% 0.2 250);
            --void: oklch(4% 0.02 250);
            --glass-surface: oklch(12% 0.04 250 / 0.6);
            --glass-edge: oklch(100% 0 0 / 0.06);
            --text-primary: oklch(96% 0.005 250);
            --text-secondary: oklch(55% 0.02 250);
            --text-accent-m: oklch(72% 0.22 330);
            --text-accent-c: oklch(72% 0.18 250);
            --scroll-velocity: 0;
        }.sc-tw *,.sc-tw *::before,.sc-tw *::after{
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }.sc-tw html{
            scroll-behavior: smooth;
            scrollbar-width: thin;
            scrollbar-color: oklch(30% 0.08 250) transparent;
        }.sc-tw{
            font-family: 'Inter Tight', sans-serif;
            background: var(--void);
            color: var(--text-primary);
            overflow-x: hidden;
            cursor: none;
        }.sc-tw .mono{
            font-family: 'JetBrains Mono', monospace;
        }.sc-tw .custom-cursor{
            position: fixed;
            top: 0;
            left: 0;
            width: 12px;
            height: 12px;
            border-radius: 50%;
            background: var(--neon-magenta);
            pointer-events: none;
            z-index: 9999;
            mix-blend-mode: plus-lighter;
            transition: transform 0.1s ease, width 0.3s ease, height 0.3s ease;
            transform: translate(-50%, -50%);
            box-shadow: 0 0 20px 4px oklch(65% 0.3 330 / 0.6);
        }.sc-tw .cursor-trail{
            position: fixed;
            top: 0;
            left: 0;
            width: 40px;
            height: 40px;
            border-radius: 50%;
            border: 1px solid oklch(60% 0.2 250 / 0.4);
            pointer-events: none;
            z-index: 9998;
            transform: translate(-50%, -50%);
            transition: transform 0.18s cubic-bezier(0.25, 0.46, 0.45, 0.94), opacity 0.3s;
            mix-blend-mode: plus-lighter;
        }.sc-tw .scene-root{
            position: relative;
            min-height: 100vh;
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            grid-template-rows: auto;
        }.sc-tw .portal-container{
            position: fixed;
            top: 0;
            right: 0;
            width: 38vw;
            height: 100vh;
            z-index: 0;
            pointer-events: none;
        }.sc-tw .portal-video{
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 1;
            filter: none;
        }.sc-tw .portal-canvas{
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            mix-blend-mode: plus-lighter;
            pointer-events: none;
        }.sc-tw .light-corridor{
            position: fixed;
            top: 0;
            right: 0;
            width: 42vw;
            height: 100vh;
            background: transparent;
            backdrop-filter: none;
            mix-blend-mode: normal;
            pointer-events: none;
            z-index: 1;
        }.sc-tw .content-layer{
            position: relative;
            z-index: 10;
            grid-column: 1 / 3;
            padding: 0 3rem;
        }.sc-tw .nav-bar{
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 100;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 1.5rem 3rem;
            background: oklch(4% 0.02 250 / 0.7);
            backdrop-filter: blur(24px) saturate(1.4);
            border-bottom: 1px solid var(--glass-edge);
        }.sc-tw .nav-logo{
            font-size: 1.1rem;
            font-weight: 700;
            letter-spacing: 0.3em;
            text-transform: uppercase;
            background: linear-gradient(90deg, var(--text-primary) 0%, var(--text-accent-c) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }.sc-tw .nav-links{
            display: flex;
            gap: 2.5rem;
            list-style: none;
        }.sc-tw .nav-links a{
            font-size: 0.7rem;
            font-weight: 500;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: var(--text-secondary);
            text-decoration: none;
            transition: color 0.3s ease;
            font-family: 'JetBrains Mono', monospace;
        }.sc-tw .nav-links a:hover{
            color: var(--text-primary);
        }.sc-tw .nav-status{
            display: flex;
            align-items: center;
            gap: 0.6rem;
            font-size: 0.65rem;
            font-family: 'JetBrains Mono', monospace;
            color: var(--text-accent-m);
            letter-spacing: 0.1em;
        }.sc-tw .status-dot{
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--neon-magenta);
            animation: pulse-dot 2s ease-in-out infinite;
            box-shadow: 0 0 8px 2px oklch(65% 0.3 330 / 0.8);
        }

        @keyframes pulse-dot {0%,100%{
                opacity: 1;
                transform: scale(1);
            }50%{
                opacity: 0.4;
                transform: scale(0.7);
            }
        }.sc-tw .hero-section{
            padding-top: 14rem;
            padding-bottom: 8rem;
        }.sc-tw .hero-eyebrow{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.65rem;
            font-weight: 400;
            letter-spacing: 0.25em;
            text-transform: uppercase;
            color: var(--text-accent-c);
            margin-bottom: 2rem;
            display: flex;
            align-items: center;
            gap: 1rem;
        }.sc-tw .hero-eyebrow::before{
            content: '';
            display: block;
            width: 2rem;
            height: 1px;
            background: var(--electric-cyan);
            box-shadow: 0 0 6px oklch(60% 0.2 250);
        }.sc-tw .hero-title{
            font-size: clamp(3.5rem, 7vw, 7rem);
            font-weight: 800;
            line-height: 0.9;
            letter-spacing: -0.04em;
            margin-bottom: 2rem;
            font-variation-settings: 'wght' var(--title-weight, 800), 'wdth' var(--title-width, 100);
            transition: font-variation-settings 0.1s linear;
        }.sc-tw .hero-title .line-1{
            display: block;
            color: var(--text-primary);
        }.sc-tw .hero-title .line-2{
            display: block;
            background: linear-gradient(90deg, var(--neon-magenta) 0%, var(--electric-cyan) 60%, var(--text-primary) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            background-size: 200% 100%;
            animation: gradient-shift 8s ease-in-out infinite;
        }

        @keyframes gradient-shift {0%,100%{
                background-position: 0% 50%;
            }50%{
                background-position: 100% 50%;
            }
        }.sc-tw .hero-subtitle{
            font-size: clamp(0.9rem, 1.4vw, 1.1rem);
            font-weight: 300;
            line-height: 1.7;
            color: var(--text-secondary);
            max-width: 44ch;
            margin-bottom: 3rem;
            letter-spacing: 0.01em;
        }.sc-tw .hero-cta-group{
            display: flex;
            gap: 1rem;
            align-items: center;
        }.sc-tw .btn-primary{
            position: relative;
            padding: 0.85rem 2.2rem;
            font-size: 0.75rem;
            font-weight: 600;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            font-family: 'JetBrains Mono', monospace;
            color: var(--void);
            background: linear-gradient(135deg, oklch(72% 0.22 330), oklch(68% 0.18 250));
            border: none;
            border-radius: 2px;
            cursor: none;
            overflow: hidden;
            transition: box-shadow 0.3s ease, transform 0.2s ease;
        }.sc-tw .btn-primary::before{
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, oklch(85% 0.05 0 / 0.4) 0%, transparent 50%, oklch(85% 0.05 0 / 0.2) 100%);
            opacity: 0;
            transition: opacity 0.3s ease;
            mask-image: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), black 30%, transparent 70%);
        }.sc-tw .btn-primary:hover{
            box-shadow: 0 0 30px 8px oklch(65% 0.3 330 / 0.4), 0 0 60px 20px oklch(60% 0.2 250 / 0.2);
            transform: translateY(-1px);
        }.sc-tw .btn-primary:hover::before{
            opacity: 1;
        }.sc-tw .btn-ghost{
            position: relative;
            padding: 0.85rem 2.2rem;
            font-size: 0.75rem;
            font-weight: 500;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            font-family: 'JetBrains Mono', monospace;
            color: var(--text-secondary);
            background: transparent;
            border: 1px solid oklch(100% 0 0 / 0.08);
            border-radius: 2px;
            cursor: none;
            overflow: hidden;
            transition: color 0.3s ease, border-color 0.3s ease;
        }.sc-tw .btn-ghost:hover{
            color: var(--text-primary);
            border-color: oklch(100% 0 0 / 0.2);
        }.sc-tw .metrics-bar{
            display: flex;
            gap: 3rem;
            padding: 2rem 0;
            border-top: 1px solid var(--glass-edge);
            margin-top: 5rem;
        }.sc-tw .metric-item{
            flex: 1;
        }.sc-tw .metric-value{
            font-size: clamp(2rem, 4vw, 3.5rem);
            font-weight: 800;
            line-height: 1;
            letter-spacing: -0.03em;
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--text-accent-c) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }.sc-tw .metric-label{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.6rem;
            font-weight: 400;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-secondary);
            margin-top: 0.4rem;
        }.sc-tw .bento-section{
            padding: 6rem 0;
        }.sc-tw .section-header{
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            margin-bottom: 3rem;
        }.sc-tw .section-title{
            font-size: clamp(1.8rem, 3vw, 2.8rem);
            font-weight: 700;
            letter-spacing: -0.03em;
            line-height: 1;
        }.sc-tw .section-tag{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.6rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-accent-m);
            padding-bottom: 0.3rem;
        }.sc-tw .bento-grid{
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            grid-template-rows: auto;
            gap: 1px;
            background: oklch(100% 0 0 / 0.04);
            border: 1px solid oklch(100% 0 0 / 0.04);
            border-radius: 4px;
            overflow: hidden;
        }.sc-tw .bento-cell{
            background: var(--glass-surface);
            padding: 2.5rem;
            position: relative;
            overflow: hidden;
            transition: background 0.4s ease;
        }.sc-tw .bento-cell::before{
            content: '';
            position: absolute;
            inset: 0;
            background: radial-gradient(ellipse at var(--cx, 50%) var(--cy, 50%), oklch(65% 0.3 330 / 0.06) 0%, transparent 60%);
            opacity: 0;
            transition: opacity 0.4s ease;
        }.sc-tw .bento-cell:hover::before{
            opacity: 1;
        }.sc-tw .bento-cell:hover{
            background: oklch(14% 0.05 250 / 0.7);
        }.sc-tw .cell-a{
            grid-column: 1 / 6;
            grid-row: 1 / 2;
        }.sc-tw .cell-b{
            grid-column: 6 / 9;
            grid-row: 1 / 2;
        }.sc-tw .cell-c{
            grid-column: 9 / 13;
            grid-row: 1 / 3;
        }.sc-tw .cell-d{
            grid-column: 1 / 4;
            grid-row: 2 / 3;
        }.sc-tw .cell-e{
            grid-column: 4 / 6;
            grid-row: 2 / 3;
        }.sc-tw .cell-f{
            grid-column: 6 / 9;
            grid-row: 2 / 3;
        }.sc-tw .cell-g{
            grid-column: 1 / 5;
            grid-row: 3 / 4;
        }.sc-tw .cell-h{
            grid-column: 5 / 9;
            grid-row: 3 / 4;
        }.sc-tw .cell-i{
            grid-column: 9 / 13;
            grid-row: 3 / 4;
        }.sc-tw .cell-label{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.55rem;
            font-weight: 500;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-accent-m);
            margin-bottom: 1.2rem;
            display: flex;
            align-items: center;
            gap: 0.6rem;
        }.sc-tw .cell-label::before{
            content: '';
            display: block;
            width: 1rem;
            height: 1px;
            background: currentColor;
            box-shadow: 0 0 4px currentColor;
        }.sc-tw .cell-heading{
            font-size: clamp(1.4rem, 2.5vw, 2.2rem);
            font-weight: 700;
            letter-spacing: -0.025em;
            line-height: 1.05;
            margin-bottom: 1rem;
        }.sc-tw .cell-body{
            font-size: 0.82rem;
            line-height: 1.75;
            color: var(--text-secondary);
            font-weight: 300;
        }.sc-tw .cell-number{
            font-size: clamp(3rem, 6vw, 5.5rem);
            font-weight: 800;
            letter-spacing: -0.05em;
            line-height: 1;
            background: linear-gradient(135deg, var(--neon-magenta) 0%, var(--electric-cyan) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }.sc-tw .cell-number-unit{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.65rem;
            letter-spacing: 0.15em;
            color: var(--text-secondary);
            margin-top: 0.5rem;
        }.sc-tw .inset-card{
            box-shadow:
                inset 0 2px 4px oklch(0% 0 0 / 0.5),
                inset 0 -1px 2px oklch(100% 0 0 / 0.04),
                inset 2px 0 4px oklch(0% 0 0 / 0.3),
                inset -2px 0 4px oklch(0% 0 0 / 0.3),
                0 1px 0 oklch(100% 0 0 / 0.06);
            background: oklch(6% 0.03 250 / 0.8);
        }.sc-tw .flow-diagram{
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
            margin-top: 1.5rem;
        }.sc-tw .flow-node{
            display: flex;
            align-items: center;
            gap: 1rem;
            padding: 0.7rem 1rem;
            background: oklch(8% 0.04 250 / 0.6);
            border-radius: 2px;
            border-left: 2px solid transparent;
            transition: border-color 0.3s ease, background 0.3s ease;
            position: relative;
            overflow: hidden;
        }.sc-tw .flow-node::after{
            content: '';
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 0%;
            background: linear-gradient(90deg, oklch(65% 0.3 330 / 0.1), transparent);
            transition: width 0.6s cubic-bezier(0.16, 1, 0.3, 1);
        }.sc-tw .flow-node:hover::after{
            width: 100%;
        }.sc-tw .flow-node:hover{
            border-left-color: var(--neon-magenta);
        }.sc-tw .flow-node-icon{
            width: 28px;
            height: 28px;
            border-radius: 1px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.65rem;
            flex-shrink: 0;
            font-family: 'JetBrains Mono', monospace;
            font-weight: 700;
        }.sc-tw .flow-node-text{
            font-size: 0.75rem;
            color: var(--text-secondary);
            font-weight: 400;
        }.sc-tw .flow-node-val{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.65rem;
            color: var(--text-accent-c);
            margin-left: auto;
        }.sc-tw .spectrum-bar{
            height: 4px;
            border-radius: 2px;
            background: linear-gradient(90deg, var(--neon-magenta), var(--electric-cyan));
            box-shadow: 0 0 12px 2px oklch(65% 0.3 330 / 0.4);
            margin-bottom: 0.8rem;
            position: relative;
            overflow: hidden;
        }.sc-tw .spectrum-bar::after{
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(90deg, transparent, oklch(100% 0 0 / 0.4), transparent);
            animation: shimmer-bar 2.5s ease-in-out infinite;
        }

        @keyframes shimmer-bar {0%{
                transform: translateX(-100%);
            }100%{
                transform: translateX(100%);
            }
        }.sc-tw .neural-grid{
            position: absolute;
            inset: 0;
            opacity: 0.06;
            background-image:
                linear-gradient(oklch(100% 0 0 / 1) 1px, transparent 1px),
                linear-gradient(90deg, oklch(100% 0 0 / 1) 1px, transparent 1px);
            background-size: 40px 40px;
            pointer-events: none;
        }.sc-tw .data-stream{
            margin-top: 1.5rem;
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
        }.sc-tw .stream-row{
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 0.5rem 0;
            border-bottom: 1px solid oklch(100% 0 0 / 0.04);
            font-family: 'JetBrains Mono', monospace;
        }.sc-tw .stream-key{
            font-size: 0.6rem;
            color: var(--text-secondary);
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }.sc-tw .stream-val{
            font-size: 0.7rem;
            color: var(--text-accent-c);
            font-weight: 600;
        }.sc-tw .live-badge{
            display: inline-flex;
            align-items: center;
            gap: 0.4rem;
            padding: 0.25rem 0.7rem;
            background: oklch(65% 0.3 330 / 0.12);
            border: 1px solid oklch(65% 0.3 330 / 0.25);
            border-radius: 100px;
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.55rem;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: var(--text-accent-m);
        }.sc-tw .velocity-section{
            padding: 8rem 0;
            position: relative;
        }.sc-tw .velocity-text{
            font-size: clamp(4rem, 10vw, 10rem);
            font-weight: 900;
            letter-spacing: -0.06em;
            line-height: 0.85;
            color: oklch(100% 0 0 / 0.03);
            text-transform: uppercase;
            user-select: none;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            white-space: nowrap;
            font-variation-settings: 'wght' var(--velocity-weight, 900);
        }.sc-tw .velocity-content{
            position: relative;
            z-index: 2;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 6rem;
            align-items: center;
            padding: 4rem 0;
        }.sc-tw .velocity-headline{
            font-size: clamp(2rem, 4vw, 3.5rem);
            font-weight: 700;
            letter-spacing: -0.03em;
            line-height: 1;
            margin-bottom: 1.5rem;
        }.sc-tw .velocity-desc{
            font-size: 0.875rem;
            line-height: 1.8;
            color: var(--text-secondary);
            font-weight: 300;
            margin-bottom: 2rem;
        }.sc-tw .kinetic-counter{
            display: flex;
            flex-direction: column;
            gap: 2rem;
        }.sc-tw .counter-item{
            display: flex;
            align-items: center;
            gap: 1.5rem;
            padding: 1.5rem;
            background: oklch(8% 0.04 250 / 0.5);
            border: 1px solid var(--glass-edge);
            border-radius: 2px;
            position: relative;
            overflow: hidden;
        }.sc-tw .counter-item::before{
            content: '';
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 3px;
            background: linear-gradient(180deg, var(--neon-magenta), var(--electric-cyan));
            box-shadow: 0 0 12px 2px oklch(65% 0.3 330 / 0.6);
        }.sc-tw .counter-num{
            font-size: 2.2rem;
            font-weight: 800;
            letter-spacing: -0.04em;
            line-height: 1;
            color: var(--text-primary);
            white-space: nowrap;
        }.sc-tw .counter-label{
            font-size: 0.75rem;
            color: var(--text-secondary);
            font-weight: 300;
            line-height: 1.5;
        }.sc-tw .counter-sub{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.6rem;
            color: var(--text-accent-c);
            margin-top: 0.25rem;
        }.sc-tw .footer-section{
            padding: 6rem 0 3rem;
            border-top: 1px solid var(--glass-edge);
        }.sc-tw .footer-grid{
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 4rem;
        }.sc-tw .footer-brand{
            font-size: 1.4rem;
            font-weight: 800;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            margin-bottom: 1rem;
            background: linear-gradient(90deg, var(--text-primary), var(--text-accent-c));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }.sc-tw .footer-desc{
            font-size: 0.8rem;
            color: var(--text-secondary);
            line-height: 1.7;
            font-weight: 300;
        }.sc-tw .footer-col-title{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.6rem;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            color: var(--text-secondary);
            margin-bottom: 1.2rem;
        }.sc-tw .footer-links{
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 0.7rem;
        }.sc-tw .footer-links a{
            font-size: 0.78rem;
            color: oklch(40% 0.02 250);
            text-decoration: none;
            transition: color 0.2s ease;
            font-weight: 300;
        }.sc-tw .footer-links a:hover{
            color: var(--text-primary);
        }.sc-tw .footer-bottom{
            margin-top: 4rem;
            padding-top: 1.5rem;
            border-top: 1px solid var(--glass-edge);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }.sc-tw .footer-copy{
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.58rem;
            color: oklch(30% 0.02 250);
            letter-spacing: 0.1em;
        }.sc-tw .scan-line{
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 2px;
            background: linear-gradient(90deg, transparent, var(--neon-magenta), var(--electric-cyan), transparent);
            z-index: 200;
            animation: scan 8s cubic-bezier(0.16, 1, 0.3, 1) infinite;
            opacity: 0.6;
            box-shadow: 0 0 20px 4px oklch(65% 0.3 330 / 0.4);
        }

        @keyframes scan {0%{
                top: -4px;
                opacity: 0;
            }2%{
                opacity: 0.6;
            }98%{
                opacity: 0.6;
            }100%{
                top: 100vh;
                opacity: 0;
            }
        }.sc-tw .noise-overlay{
            position: fixed;
